import { Component, Prop, h, Event, EventEmitter, Method, State, Listen } from '@stencil/core';

@Component({
  tag: 'std-autocomplete',
  styleUrl: 'std-autocomplete.css',
  shadow: true
})
export class StdAutoComplete {
  @Prop() label: string;
  @Prop() suggestions: any[] = [];
  @Prop() icon = 'search';
  @Prop() displayProp: string;
  @Prop() valueProp: string;
  @Prop() altDisplayProp: string;
  @Prop() altDisplayFn: Function;
  @Prop() placeholder: string;
  @Prop() maxLength: number;
  @Prop() minLength: number;
  @Prop() disabled = false;
  @Prop() readonly: boolean;
  @Prop() cacheItems: boolean = false;
  @Prop() interactiveState: null | 'loading' | 'error' | 'void' = null;

  // for input
  @Prop() disabledAsReadonly = false;
  @Prop() helperText: string;
  @Prop() status = 'default';

  @Event({
    bubbles: false
  })
  changeEvent: EventEmitter<string>;
  @Event() selectedEvent: EventEmitter<any>;
  @Event({
    bubbles: false
  })
  blurEvent: EventEmitter;

  @State() selectedItem: any | null = null;
  @State() isVisible: boolean = false; // Dropdown visibility
  @State() inputValue: string = ''; // Current input value

  inputElement: HTMLDivElement;

  @Method()
  async setSelectedValue(selectedItem: any) {
    let valueToEmit: any;

    if (this.valueProp) {
      this.selectedItem = typeof selectedItem === 'object' ? selectedItem : this.suggestions.find(item => item[this.valueProp] === selectedItem);
      valueToEmit = this.selectedItem ? this.selectedItem[this.valueProp] : selectedItem;
    } else {
      this.selectedItem = selectedItem;
      valueToEmit = selectedItem;
    }
    this.inputValue = this.selectedItem ? this.displayText(this.selectedItem) : selectedItem;
    this.changeEvent.emit(this.inputValue); // notify std-input about the change
    this.selectedEvent.emit(valueToEmit);
  }

  private handleInputChange(event: Event) {
    const input = event.target as HTMLInputElement;
    const newValue = input.value;
    if (this.inputValue !== newValue) {
      this.inputValue = newValue;
      this.changeEvent.emit(this.inputValue); // Emit the updated input value
      this.isVisible = true; // Ensure dropdown visibility
    }
  }

  private displayText(item: any): string {
    if (!item) return '';
    if (typeof item === 'string') return item;
    const displayText = item[this.displayProp];
    if (!displayText) {
      throw new Error(`std-autocomplete | Property '${this.displayProp}' does not exist on : ${JSON.stringify(this.suggestions)}`);
    }
    return String(displayText);
  }

  private altDisplayText(item: any): string {
    if (!item) return '';
    if (typeof item === 'string') return item;
    const displayText = this.altDisplayFn ? this.altDisplayFn(item) : item[this.altDisplayProp];
    if (!displayText) {
      throw new Error(`std-autocomplete | Property '${this.altDisplayProp}' does not exist on : ${JSON.stringify(this.suggestions)}`);
    }
    return String(displayText);
  }

  toggleVisible() {
    if (!this.cacheItems) return;
    this.isVisible = !this.isVisible;
  }

  onInputBlur(selectedItem: any | null) {
    this.blurEvent.emit(selectedItem);
  }

  @Listen('click', { target: 'document' })
  checkForClickOutside(ev: PointerEvent): void {
    const path = ev.composedPath();
    const inputElement = this.inputElement && !path.includes(this.inputElement);
    if (this.isVisible) {
      if (!this.cacheItems || inputElement) {
        this.isVisible = false;
        return;
      }
    }
  }

  render() {
    return (
      <div class="relative">
        <div onClick={() => this.toggleVisible()} ref={el => (this.inputElement = el)}>
          <std-input
            label={this.label}
            icon={this.icon}
            value={this.inputValue}
            placeholder={this.placeholder}
            maxlength={this.maxLength}
            minlength={this.minLength}
            disabled={this.disabled}
            readonly={this.readonly}
            onBlur={e => this.onInputBlur(e)}
            onInput={event => this.handleInputChange(event)}
            helperText={this.helperText}
            status={this.status}
            disabledAsReadonly={this.disabledAsReadonly}
          />
        </div>
        {this.interactiveState === 'loading' && this.isVisible && (
          <div class="absolute top-[77px] inset-x-0 w-full shadow-modal bg-white rounded-md px-1 z-10">
            <div class="flex justify-center w-full h-[112px] pt-2">
              <std-small-loader classes="w-8-sl h-8-sl animate-spin-sl" />
            </div>
          </div>
        )}

        {this.interactiveState === 'error' && this.isVisible && (
          <div class="absolute top-[77px] inset-x-0 w-full shadow-modal bg-white rounded-md px-1 z-10">
            <div class="flex gap-2 p-4">
              <i class="icon-alert text-primary text-2xl"></i>
              <div>
                <p class="text-dark text-base">Error al cargar los resultados.</p>
                <p class="text-dark text-base">Por favor, inténtalo nuevamente.</p>
              </div>
            </div>
          </div>
        )}

        {this.interactiveState === 'void' && this.isVisible && (
          <div class=" absolute top-[77px] inset-x-0 w-full shadow-modal bg-white rounded-md px-1 z-10">
            <div class="flex items-center gap-2 p-4">
              <i class="icon-warning-in-a-circle text-primary text-2xl"></i>
              <p class="text-dark text-base">No se encontraron coincidencias.</p>
            </div>
          </div>
        )}

        <div class="absolute top-full inset-x-0 w-full shadow-modal bg-white rounded-md px-1 z-10">
          {this.isVisible && this.suggestions.length > 0 && !this.interactiveState && (
            <ul class="w-full flex flex-col gap-1 py-1 max-h-[216px] overflow-y-auto">
              {this.suggestions.map(item => (
                <li
                  onClick={() => this.setSelectedValue(item)}
                  class="flex justify-between items-center gap-2 rounded hover:bg-alternative-light p-3 transition-all duration-300 cursor-pointer">
                  {this.displayProp && !this.altDisplayProp && !this.altDisplayFn && <span class="text-base text-dark">{this.displayText(item)}</span>}
                  {(this.altDisplayProp || this.altDisplayFn) && (
                    <div class="flex flex-col">
                      <span class="text-lg text-dark font-headline font-bold">{this.displayText(item)}</span>
                      <span class="text-sm text-dark">{this.altDisplayText(item)}</span>
                    </div>
                  )}
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    );
  }
}
